    // 情况2：以“请”开头，且去掉“请”后是有效假期
    if (data1.startsWith("请") && data1.length > 1) {
        const afterQing = data1.substring(1);
        if (validLeaves.includes(afterQing)) {
            return { result: normalizeMap[afterQing] ?? afterQing };
        }
    }

    // 其他所有情况
    return { result: "非快捷" };
}

