function main({data1, data2}){
    // 假期与允许性别的映射（F: 女, M: 男）
    const leaveGenderMap = {
        "产检假": "F",
        "产假": "F",
        "无薪侍产假": "M",
        "无薪产假": "F",
        "有薪产假": "F",
        "有薪侍产假": "M",
        "产前假": "F",
        "陪产假": "M",
        "哺乳假": "F"
    };

    // 初始化 sex 变量
    let sex = "";

    // 1. 解析 data1 (员工信息 JSON)
    try {
        const parsedData1 = JSON.parse(data1);
        sex = parsedData1.sex; // 提取性别字段
    } catch (e) {
        // 解析失败
        sex = ""; 
    }

    // 2. 获取假期类型 (data2)
    const leaveType = data2;

    // 定义最终结果状态，默认为不符合
    let status = "不符合";

    // 3. 判断逻辑
    // 如果假期不在预设列表中（如年假、事假），视为符合
    if (!leaveGenderMap.hasOwnProperty(leaveType)) {
        status = "符合";
    } else {
        // 在列表中：检查性别是否匹配
        // 只有当 sex 被成功提取 且 与规则匹配时，才为符合
        if (sex && leaveGenderMap[leaveType] === sex) {
            status = "符合";
        } else {
            status = "不符合";
        }
    }

    return {
        status: status,
        sex: sex,
        leaveType: leaveType // 输出假期类型方便核对
    };
}

function main({data1, data2}) {
    const holidayTypeMap = {
        "婚假": "A03",
        "丧假": "A04",
        "产检假": "A05",
        "非独生子女护理假": "A48",
        "产假": "A06",
        "病假": "B01",
        "事假": "C01",
        "育儿假": "A47",
        "调休假": "A02",
        "无薪侍产假": "C03",
        "计划生育假": "A32",
        "80%病假": "B03",
        "无薪产假": "C02",
        "调休假(综合工时)": "A35",
        "有薪产假": "B04",
        "有薪侍产假": "B02",
        "子女护理假": "A37",
        "年休假": "A31",
        "不定时员工日常休假": "A43",
        "无薪假": "C04",
        "产前假": "A33",
        "路程假": "A40",
        "全薪病假": "A49",
        "陪产假": "A08",
        "哺乳假": "A09",
        "出差": "L01",
        "公出": "L02",
    };

    // 辅助函数：将全角括号转为半角，用于匹配 holidayTypeMap 的 key
    function normalizeBrackets(str) {
        return str.replace(/（/g, '(').replace(/）/g, ')');
    }

    // 解析 data1
    let obj1;
    try {
        obj1 = JSON.parse(data1.trim());
    } catch (e) {
        return { result: "异常" };
    }

    const originalTypeName = obj1.typeName;
    const data2List = data2.split('、').map(item => item.trim());

    // 步骤1：在 data2 中查找以 typeName 开头的项（前缀匹配）
    const matchedItem = data2List.find(item => item.startsWith(originalTypeName));

    if (matchedItem === undefined) {
        return { result: "异常" };
    }

    // 步骤2：用匹配到的完整名称（如“调休假（综合工时）”）去查 holidayTypeMap
    const normalizedMatchedName = normalizeBrackets(matchedItem);
    const expectedTypeCode = holidayTypeMap[normalizedMatchedName];

    if (expectedTypeCode === undefined) {
        // 如果 map 中没有这个假期类型，视为异常
        return { result: "异常" };
    }

    // 步骤3：修正 typeName 和 typeCode
    const newObj = { ...obj1 };
    newObj.typeName = matchedItem; // 保留 data2 中的原始格式（全角括号）
    newObj.typeCode = expectedTypeCode; // 强制使用 map 中的正确 code

    // 返回修正后的 JSON 字符串
    return { result: JSON.stringify(newObj) };
}

function main({ data1 }) {
    let parsedData;
    let isJson = true;

    // 尝试解析 JSON
    try {
        parsedData = JSON.parse(data1);
        // 确保解析结果是对象（不是数组、字符串、数字等）
        if (typeof parsedData !== 'object' || parsedData === null || Array.isArray(parsedData)) {
            isJson = false;
        }
    } catch (e) {
        // 解析失败，说明是普通字符串
        isJson = false;
    }

    // 如果不是合法的对象型 JSON，原样返回
    if (!isJson) {
        return {
            result: "异常", // 或根据业务定，这里通常可视为“正常提示”
            data1: data1   // 原样输出
        };
    }

    // 以下是原逻辑：仅当是合法 JSON 对象时才处理
    const isTypeCodeEmpty = !parsedData.typeCode || parsedData.typeCode.trim() === "";
    const result = isTypeCodeEmpty ? "异常" : "正常";

    if (isTypeCodeEmpty) {
        parsedData.typeName = "";
    }

    return {
        result: result,
        data1: JSON.stringify(parsedData)
    };
}

