function main({ data1 }) {
    // 解析输入的 JSON 字符串
    const shifts = JSON.parse(data1);

    // 从后往前查找第一个非休息班（shiftCode 不以 'defaultOFF' 开头）
    for (let i = shifts.length - 1; i >= 0; i--) {
        const shift = shifts[i];
        if (!shift.shiftCode?.startsWith('defaultOFF')) {
            return {
                startTime: shift.startTime,
                endTime: shift.endTime
            };
        }
    }

    // 如果全是休息班，返回 null 或默认值
    return {
        startTime: null,
        endTime: null
    };
}

